SELECT DATE_TRUNC('MONTH', CONVERT_TIMEZONE('UTC', 'Asia/Ho_Chi_Minh', "t0"."order_date")) AS "order_date_month", COUNT(CASE WHEN "t0"."order_date" >= TIMESTAMP '2025-12-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-09-30 17:00:00' THEN 1 END) AS "order_count" FROM "sales"."orders" AS "t0" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2025-12-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-09-30 17:00:00') GROUP BY DATE_TRUNC('MONTH', CONVERT_TIMEZONE('UTC', 'Asia/Ho_Chi_Minh', "t0"."order_date")) ORDER BY "order_date_month" ASC LIMIT 1000
